import ast,json,hashlib
from pathlib import Path
root=Path('/workspace');r=json.load(open(root/'runtime.json'));p=json.load(open(root/'proposal.json'))
def check(value,schema,path):
 t=schema.get('type');typ={'object':dict,'array':list,'string':str}
 if t: assert isinstance(value,typ[t]),(path,t)
 if 'const' in schema: assert value==schema['const'],path
