oc=next(x for x in old.body if isinstance(x,ast.ClassDef)); om={x.name:ast.dump(x) for x in oc.body if isinstance(x,ast.FunctionDef)}
assert len(p['variants'])==4
assert len({v['name'] for v in p['variants']})==4
assert len({v['file'] for v in p['variants']})==4
allowed={'torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib'}
hashes={};trees=[]
for i,v in enumerate(p['variants']):
 assert Path(v['file']).name==v['file'] and v['file'].endswith('.py')
 src=(root/v['file']).read_text();tree=ast.parse(src);compile(tree,v['file'],'exec')
 cfg=next(ast.literal_eval(x.value) for x in tree.body if isinstance(x,ast.Assign) and any(isinstance(a,ast.Name) and a.id=='CONFIG' for a in x.targets))
 assert cfg==v['config'],v['name']
 for n in ast.walk(tree):
  if isinstance(n,ast.Import):assert all(a.name.split('.')[0] in allowed for a in n.names)
  if isinstance(n,ast.ImportFrom):assert n.module.split('.')[0] in allowed
  if isinstance(n,ast.Call) and isinstance(n.func,ast.Name):assert n.func.id not in {'open','exec','eval','compile','__import__','input','print'},n.func.id
  if isinstance(n,ast.Attribute):assert n.attr not in {'load','save','load_state_dict','read_text','write_text','from_pretrained','system','popen'}
 assert not any(isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef)) and n.name in ('make_optimizer','training_loss') for n in ast.walk(tree))
 cl=next(x for x in tree.body if isinstance(x,ast.ClassDef));ms={x.name:ast.dump(x) for x in cl.body if isinstance(x,ast.FunctionDef)}
 if i<3:
  for name in ['_match_counts','_statistics','_membership','_histogram','_sorted_distribution','_identity_tables','_identity_features','_dense_distribution']:
   assert ms[name]==om[name],(v['name'],name)
  trees.append(ast.dump(cl))
  # All learned lookups take only static; no learned event consumers.
  for name in ['_nonidentity_features','forward']:
   node=next(x for x in cl.body if isinstance(x,ast.FunctionDef) and x.name==name)
   assert 'history_' not in ast.get_source_segment(src,node)
 else:
  assert set(om)==set(ms)
  assert all(ms[k]==om[k] for k in om),'Reference implementation changed'
 hashes[v['name']]=hashlib.sha256(src.encode()).hexdigest()
assert len(set(trees))==1,'Compact source implementations differ beyond literal CONFIG'
for a in p['knowledge_assessments']:
 assert a['decision'] in ('used','considered','rejected','unresolved')
 assert set(a)=={'knowledge_id','decision','rationale','transformed_mechanism','variant_names','nearest_work_difference','falsifier'}
print('PASS: schema, protocol, evidence permissions, literal registrations, standalone syntax, numeric imports/no I/O, no training/optimizer hooks.')
print('PASS: all eight inherited scalar helpers identical; all original reference methods identical; compact Model ASTs identical.')
print(json.dumps(hashes,indent=2))
